    :param ctx: Invocation context for this command.
    :param incomplete: Value being completed. May be empty.

    .. versionadded:: 8.0
    """
    from click.shell_completion import CompletionItem

    results: list[CompletionItem] = []

    if incomplete and not incomplete[0].isalnum():
        for param in self.get_params(ctx):
            if (
                not isinstance(param, Option)
                or param.hidden
                or (
                    not param.multiple
                    and ctx.get_parameter_source(param.name)
                    is ParameterSource.COMMANDLINE
                )
            ):
                continue

            results.extend(
                CompletionItem(name, help=param.help)
                for name in [*param.opts, *param.secondary_opts]
                if name.startswith(incomplete)
            )

    while ctx.parent is not None:
        ctx = ctx.parent

        if isinstance(ctx.command, Group) and ctx.command.chain:
            results.extend(
                CompletionItem(name, help=command.get_short_help_str())
                for name, command in _complete_visible_commands(ctx, incomplete)
                if name not in ctx._protected_args
            )

    return results

def make_pass_decorator(
    object_type: type[T], ensure: bool = False
) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:
    """Given an object type this creates a decorator that will work
    similar to :func:`pass_obj` but instead of passing the object of the
    current context, it will find the innermost context of type
    :func:`object_type`.

    This generates a decorator that works roughly like this::

        from functools import update_wrapper

        def decorator(f):
            @pass_context
            def new_func(ctx, *args, **kwargs):
                obj = ctx.find_object(object_type)
                return ctx.invoke(f, obj, *args, **kwargs)
            return update_wrapper(new_func, f)
        return decorator

    :param object_type: the type of the object to pass.
    :param ensure: if set to `True`, a new object will be created and
                   remembered on the context if it's not there yet.
    """

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:
        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()

            obj: T | None
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)

            if obj is None:
                raise RuntimeError(
                    "Managed to invoke callback without a context"
                    f" object of type {object_type.__name__!r}"
                    " existing."
                )

            return ctx.invoke(f, obj, *args, **kwargs)

        return update_wrapper(new_func, f)

    return decorator

def _echo_aborted() -> None:
    """Write the final abort message to standard error."""
    echo(_("Aborted!"), file=sys.stderr)

        if not standalone_mode:
            raise Abort() from e

        report = _echo_aborted
    except ClickException as e:
        if not standalone_mode:
            raise

        report, exit_code = e.show, e.exit_code
    except OSError as e:
        if e.errno != errno.EPIPE:
            raise

        sys.stdout = t.cast(t.TextIO, _PacifyFlushWrapper(sys.stdout))
        sys.stderr = t.cast(t.TextIO, _PacifyFlushWrapper(sys.stderr))

    if report is not None:
        report()

    sys.exit(exit_code)
except (EOFError, KeyboardInterrupt):
    if not standalone_mode:
        raise

    sys.exit(exit_code)

def format_bar(self) -> str:
    if self.length is not None:
        bar_length = int(self.pct * self.width)
        bar = self.fill_char * bar_length
        bar += self.empty_char * (self.width - bar_length)
    elif self.finished:
        bar = self.fill_char * self.width
    else:
        chars = list(self.empty_char * (self.width or 1))
        if self.time_per_iteration != 0:
            chars[
                int(
                    (math.cos(self.pos * self.time_per_iteration) / 2.0 + 0.5)
                    * self.width
                )
            ] = self.fill_char
        bar = "".join(chars)
    return bar
